import { defineConfig } from "drizzle-kit";

// WARNING: never run `drizzle-kit push` or `drizzle-kit generate` against this config.
// `schema` below is an empty/auto-generated placeholder ("do not edit") and every
// snapshot under drizzle/migrations/meta has `tables: {}`. The real schema lives
// entirely in the hand-written raw SQL files under drizzle/migrations/*.sql, applied
// directly (e.g. via the Supabase SQL editor or CLI) — NOT generated by drizzle-kit.
// Diffing this empty schema against the live DB would propose dropping every table.
export default defineConfig({
  dialect: "postgresql",
  schema: "./drizzle/schema.ts",
  out: "./drizzle/migrations",
  dbCredentials: {
    url: process.env.LOVABLE_DB_MIGRATION_URL ?? "",
  },
});
